// Generates src/layouts/v3/theme/tokens.css from src/layouts/v3/theme/tokens.json.
//
// Run by hand after copying a new tokens.json from the design system:
//   node scripts/generate-v3-tokens.mjs
// It is NOT part of the build; tokens.test.js regenerates in memory and fails
// when the committed tokens.css drifted from the JSON.
import { readFileSync, writeFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const HEADER =
  '/* GENERATED by scripts/generate-v3-tokens.mjs from theme/tokens.json — do not edit by hand. */'

// The island is dark in both themes, so the pet name inside it always uses the
// DARK value of the module ink (the light value of tiq-ink is 1.55:1 on it).
// Derived from the JSON, never typed: pet name -> [color token, theme].
export const ISLAND_NAME_SOURCES = {
  bit: ['bit', 'dark'],
  tiq: ['tiq-ink', 'dark'],
  fin: ['fin-ink', 'dark'],
  kan: ['kan-ink', 'dark'],
  navi: ['navi-ink', 'dark'],
}

const FAMILY_VARIABLE = {
  display: '--v3-font-display',
  sans: '--v3-font-sans',
  mono: '--v3-font-mono',
}

function line(name, value) {
  return `  --v3-${name}: ${value};`
}

function themedColorLines(tokens, theme) {
  return tokens.map((token) => line(token.name, token.value[theme].toLowerCase()))
}

function typeStyles(tokens) {
  return tokens.type.groups.flatMap((group) =>
    group.styles.map((style) => ({ ...style, family: group.family })),
  )
}

function typeVariableLines(tokens) {
  const lines = []
  for (const style of typeStyles(tokens)) {
    const base = `type-${style.name}`
    lines.push(line(`${base}-size`, style.fontSize))
    lines.push(line(`${base}-line`, style.lineHeight))
    lines.push(line(`${base}-weight`, String(style.fontWeight)))
    if (style.letterSpacing) lines.push(line(`${base}-tracking`, style.letterSpacing))
  }
  return lines
}

function typeClassBlocks(tokens) {
  return typeStyles(tokens).map((style) => {
    const base = `--v3-type-${style.name}`
    const body = [
      `  font-family: var(${FAMILY_VARIABLE[style.family]});`,
      `  font-size: var(${base}-size);`,
      `  line-height: var(${base}-line);`,
      `  font-weight: var(${base}-weight);`,
    ]
    if (style.letterSpacing) body.push(`  letter-spacing: var(${base}-tracking);`)
    if (style.name === 'eyebrow') body.push('  text-transform: uppercase;')
    return `.v3-type-${style.name} {\n${body.join('\n')}\n}`
  })
}

function islandNameLines(tokens) {
  return Object.entries(ISLAND_NAME_SOURCES).map(([pet, [colorName, theme]]) => {
    const token = tokens.color.tokens.find((entry) => entry.name === colorName)
    if (!token) throw new Error(`Island name source "${colorName}" missing from tokens.json`)
    return line(`island-name-${pet}`, token.value[theme].toLowerCase())
  })
}

export function generateTokensCss(tokens) {
  const unthemed = [
    ...Object.entries(FAMILY_VARIABLE).map(([family, variable]) =>
      `  ${variable}: ${tokens.type.families[family]};`,
    ),
    ...tokens.spacing.tokens.map((token) => line(token.name, token.value)),
    ...tokens.radius.tokens.map((token) => line(token.name, token.value)),
    ...tokens.size.tokens.map((token) => line(token.name, token.value)),
    ...tokens.movimento.tokens.map((token) => line(token.name, token.value)),
    ...typeVariableLines(tokens),
    ...islandNameLines(tokens),
  ]

  const themeBlock = (theme) => {
    const lines = [
      ...themedColorLines(tokens.color.tokens, theme),
      ...tokens.shadow.tokens.map((token) => line(token.name, token.value[theme])),
    ]
    return `:root[data-layout="v3"][data-theme="${theme}"] {\n${lines.join('\n')}\n}`
  }

  return [
    HEADER,
    `:root[data-layout="v3"] {\n${unthemed.join('\n')}\n}`,
    themeBlock('light'),
    themeBlock('dark'),
    ...typeClassBlocks(tokens),
  ].join('\n') + '\n'
}

const here = path.dirname(fileURLToPath(import.meta.url))
const THEME_DIR = path.resolve(here, '..', 'src', 'layouts', 'v3', 'theme')

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const tokens = JSON.parse(readFileSync(path.join(THEME_DIR, 'tokens.json'), 'utf8'))
  writeFileSync(path.join(THEME_DIR, 'tokens.css'), generateTokensCss(tokens))
  console.log('Wrote src/layouts/v3/theme/tokens.css')
}
